#ifdef _WIN32
/* WIN3-B: POSIX socket compat over Winsock (socket programs only). */
#ifndef F_GETFL
#define F_GETFL 3
#endif
#ifndef F_SETFL
#define F_SETFL 4
#endif
#ifndef O_NONBLOCK
#define O_NONBLOCK 0x800
#endif
void tur_wsa_ensure(void){
    static LONG __done = 0;
    if (InterlockedExchange(&__done, 1) == 0) { WSADATA __w; WSAStartup(MAKEWORD(2,2), &__w); }
}
void tur_wsa_seterrno(void){
    int __e = WSAGetLastError();
    if (__e == WSAEWOULDBLOCK) errno = EWOULDBLOCK;
    else if (__e == WSAEINPROGRESS) errno = EINPROGRESS;
    else if (__e) errno = __e;
}
int tur_compat_socket(int __af,int __ty,int __pr){ tur_wsa_ensure(); return (int)socket(__af,__ty,__pr); }
int tur_compat_fcntl(int __fd,int __cmd,int __arg){
    if (__cmd == F_SETFL) { u_long __m = (__arg & O_NONBLOCK) ? 1 : 0; return ioctlsocket((SOCKET)__fd, FIONBIO, &__m); }
    return 0;
}
int tur_compat_recv(int __fd,void*__b,size_t __n,int __f){ int __r = recv((SOCKET)__fd,(char*)__b,(int)__n,__f); if (__r<0) tur_wsa_seterrno(); return __r; }
int tur_compat_send(int __fd,const void*__b,size_t __n,int __f){ int __r = send((SOCKET)__fd,(const char*)__b,(int)__n,__f); if (__r<0) tur_wsa_seterrno(); return __r; }
int tur_compat_accept(int __fd,struct sockaddr*__a,socklen_t*__l){ SOCKET __s = accept((SOCKET)__fd,__a,__l); if (__s==INVALID_SOCKET){ tur_wsa_seterrno(); return -1; } return (int)__s; }
int tur_compat_connect(int __fd,const struct sockaddr*__a,socklen_t __l){
    int __r = connect((SOCKET)__fd,__a,(int)__l);
    if (__r != 0) { errno = (WSAGetLastError()==WSAEWOULDBLOCK) ? EINPROGRESS : WSAGetLastError(); }
    return __r;
}
int tur_compat_close(int __fd){ int __t; int __tl=(int)sizeof(__t); if (getsockopt((SOCKET)__fd,SOL_SOCKET,SO_TYPE,(char*)&__t,&__tl)==0) return closesocket((SOCKET)__fd); return _close(__fd); }
int tur_compat_setsockopt(int __fd,int __lv,int __opt,const void*__v,socklen_t __l){
    if (__lv == SOL_SOCKET && __opt == SO_REUSEADDR) return 0;
    if (__lv == SOL_SOCKET && (__opt == SO_RCVTIMEO || __opt == SO_SNDTIMEO)
        && __l == (socklen_t)sizeof(struct timeval)) {
        const struct timeval *__tv = (const struct timeval *)__v;
        DWORD __ms = (DWORD)(__tv->tv_sec * 1000L + __tv->tv_usec / 1000L);
        return setsockopt((SOCKET)__fd,__lv,__opt,(const char*)&__ms,(int)sizeof(__ms));
    }
    return setsockopt((SOCKET)__fd,__lv,__opt,(const char*)__v,(int)__l);
}
int tur_compat_getsockopt(int __fd,int __lv,int __opt,void*__v,socklen_t*__l){
    int __n = __l ? (int)*__l : 0;
    int __r = getsockopt((SOCKET)__fd,__lv,__opt,(char*)__v,__l ? &__n : NULL);
    if (__l) *__l = (socklen_t)__n;
    return __r;
}
#define socket(a,b,c)  tur_compat_socket((a),(b),(c))
#define fcntl(a,b,c)   tur_compat_fcntl((a),(b),(c))
#define recv(a,b,c,d)  tur_compat_recv((a),(b),(c),(d))
#define send(a,b,c,d)  tur_compat_send((a),(b),(c),(d))
#define accept(a,b,c)  tur_compat_accept((a),(b),(c))
#define connect(a,b,c) tur_compat_connect((a),(b),(c))
#define close(a)       tur_compat_close((a))
#define setsockopt(a,b,c,d,e) tur_compat_setsockopt((a),(b),(c),(d),(e))
#define getsockopt(a,b,c,d,e) tur_compat_getsockopt((a),(b),(c),(d),(e))
#endif /* _WIN32 */
#define TUR_TEST_REGISTRY_MAX 1024
#define BACKTRACK_DEPTH_DEFAULT 0
typedef int64_t (*tur_test_callback_t)(void);
const char *tur_test_registry_names[TUR_TEST_REGISTRY_MAX];
tur_test_callback_t tur_test_registry_fns[TUR_TEST_REGISTRY_MAX];
int64_t tur_test_registry_count = 0;

int64_t tur_test_register(const char *name, void *test_fn) {
    if (!test_fn) return 0;
    if (tur_test_registry_count >= TUR_TEST_REGISTRY_MAX) return 0;
    tur_test_registry_names[tur_test_registry_count] = name ? name : "<unnamed>";
    tur_test_registry_fns[tur_test_registry_count] = (tur_test_callback_t)test_fn;
    tur_test_registry_count++;
    return 1;
}

int64_t tur_test_run_all(void) {
    int64_t passed = 0;
    int64_t failed = 0;
    for (int64_t i = 0; i < tur_test_registry_count; i++) {
        tur_test_callback_t fn = tur_test_registry_fns[i];
        int64_t rc = fn ? fn() : 0;
        if (rc == 1) {
            putchar('.');
            putchar('\n');
            passed++;
        } else {
            putchar('F');
            putchar('\n');
            printf("%s\n", tur_test_registry_names[i]);
            failed++;
        }
    }
    printf("summary: %lld passed, %lld failed\n",
           (long long)passed, (long long)failed);
    return failed == 0 ? 0 : 1;
}

/* tur_frame - phase 4 v1 lowering (from runtime.h) */
typedef void (*defer_fn_t)(void *env);
#define TUR_FRAME_MAX_DEFERS 32

typedef struct tur_frame {
    defer_fn_t defers[TUR_FRAME_MAX_DEFERS];
    void *envs[TUR_FRAME_MAX_DEFERS];
    int n;
    struct tur_frame *parent;
    bool may_capture;
} tur_frame;

void tur_frame_init(tur_frame *f, tur_frame *parent) {
    f->n = 0; f->parent = parent; f->may_capture = false;
}
int tur_frame_push_defer(tur_frame *f, defer_fn_t thunk, void *env) {
    if (f->n >= TUR_FRAME_MAX_DEFERS) return -1;
    f->defers[f->n] = thunk;
    f->envs[f->n] = env;
    f->n++;
    return 0;
}
void tur_frame_fire_lifo(tur_frame *f) {
    for (int i = f->n - 1; i >= 0; i--) f->defers[i](f->envs[i]);
    f->n = 0;
}
void tur_frame_fire_chain(tur_frame *f) {
    for (tur_frame *cur = f; cur != NULL; cur = cur->parent) {
        tur_frame_fire_lifo(cur);
    }
}

/* Phase R2: tur_panic */
int tur_panic_in_progress = 0;
tur_frame *global_panic_frame = NULL;
int64_t g_tur_args = 0;  /* *args*: CLI arguments as list of :cstr (set in main) */
const char *g_tur_argv0 = "";  /* *argv0*: the program's own name, argv[0] (set in main) */
void tur_panic_set_frame(tur_frame *f) {
    global_panic_frame = f;
}

typedef struct tur_panic_payload tur_panic_payload;
typedef struct tur_handler_node { jmp_buf buf; struct tur_handler_node *parent; } tur_handler_node;
#if defined(__GNUC__) || defined(__clang__)
extern void ** tur_tls_handler_chain_ptr(void);
#define tur_handler_chain (*(tur_handler_node * *)tur_tls_handler_chain_ptr())
#else
extern void ** tur_tls_handler_chain_ptr(void);
#define tur_handler_chain (*(tur_handler_node **)tur_tls_handler_chain_ptr())
#endif
#if defined(__GNUC__) || defined(__clang__)
extern int * tur_tls_panicking_ptr(void);
#define tur_panicking (*tur_tls_panicking_ptr())
#else
extern int * tur_tls_panicking_ptr(void);
#define tur_panicking (*tur_tls_panicking_ptr())
#endif
#define TUR_SC_MAXP 8
#define TUR_SC_MAXN 32
typedef struct tur_cont { int tag; tur_handler_node *boundary; struct tur_cont *next; int64_t saved[TUR_SC_MAXN]; uint32_t aggr_mask; } tur_cont;
int64_t tur_sc_bits_f64(double d){ int64_t i; memcpy(&i,&d,sizeof i); return i; }
double  tur_sc_f64_from_bits(int64_t i){ double d; memcpy(&d,&i,sizeof d); return d; }
int64_t tur_sc_bits_f32(float f){ int64_t i=0; memcpy(&i,&f,sizeof f); return i; }
float   tur_sc_f32_from_bits(int64_t i){ float f; memcpy(&f,&i,sizeof f); return f; }
tur_panic_payload *global_panic_payload;
tur_panic_payload *panic_payload_new(int, void *, const char *, int, int);
void tur_panic_at(const char *file, int line, const char *msg) {
    if (tur_panic_in_progress) {
        fprintf(stderr, "double panic: aborting\n");
        abort();
    }
    tur_panic_in_progress = 1;
    if (tur_handler_chain) {
        global_panic_payload = panic_payload_new(5, msg ? strdup(msg) : NULL, file, line, 1);
        if (global_panic_frame) { tur_frame_fire_chain(global_panic_frame); global_panic_frame = NULL; }
        tur_panicking = 1;
        return;
    }
    fprintf(stderr, "panic at %s:%d: %s\n", file, line, msg ? msg : "(no message)");
    if (global_panic_frame) {
        tur_frame_fire_chain(global_panic_frame);
    }
    fflush(NULL);
    abort();
}
void tur_panic(const char *msg) { tur_panic_at(__FILE__, __LINE__, msg); }

/* Phase R5: tur_panic_abort - no unwinding, immediate abort */
void tur_panic_abort(const char *msg) {
    fprintf(stderr, "panic (no unwind): %s\n", msg ? msg : "(no message)");
    abort();
}

