/* TC0: per-thread cancel state for cooperative POSIX-thread cancellation */
typedef struct {
    volatile int    cancel_requested;  /* set by canceller via tur_thread_cancel */
    pthread_mutex_t cancel_mutex;
    pthread_cond_t  cancel_cond;
} TurThreadState;

typedef struct {
    pthread_t        tid;
    TurThreadState  *state;  /* heap-allocated; owned by this handle */
} TurThreadHandle;

typedef struct {
    void           *(*user_fn)(void *);
    void           *user_arg;
    TurThreadState *state;
} TurThreadSpawnArg;

/* TC0: thread-local pointer to this thread's cancel state (NULL on main thread) */
#if defined(__GNUC__) || defined(__clang__)
extern void ** tur_tls_current_thread_state_ptr(void);
#define tur_current_thread_state (*(TurThreadState * *)tur_tls_current_thread_state_ptr())
#else
extern void ** tur_tls_current_thread_state_ptr(void);
#define tur_current_thread_state (*(TurThreadState **)tur_tls_current_thread_state_ptr())
#endif
/* TC0: thread-local setjmp buffer for with-cancel-guard (0 = not active) */
#if defined(__GNUC__) || defined(__clang__)
extern jmp_buf * tur_tls_cancel_jmpbuf_ptr(void);
#define tur_cancel_jmpbuf (*tur_tls_cancel_jmpbuf_ptr())
#else
extern tur_jmp_buf * tur_tls_cancel_jmpbuf_ptr(void);
#define tur_cancel_jmpbuf (*tur_tls_cancel_jmpbuf_ptr())
#endif
#if defined(__GNUC__) || defined(__clang__)
extern int * tur_tls_cancel_jmpbuf_valid_ptr(void);
#define tur_cancel_jmpbuf_valid (*tur_tls_cancel_jmpbuf_valid_ptr())

#else
extern int * tur_tls_cancel_jmpbuf_valid_ptr(void);
#define tur_cancel_jmpbuf_valid (*tur_tls_cancel_jmpbuf_valid_ptr())
#endif
void *tur_thread_trampoline(void *raw) {
    TurThreadSpawnArg *a = (TurThreadSpawnArg *)raw;
    tur_current_thread_state = a->state;
    void *(*fn)(void *) = a->user_fn;
    void *user_arg = a->user_arg;
    free(a);
    return fn(user_arg);
}

int tur_thread_cancel_requested(void) {
    TurThreadState *s = tur_current_thread_state;
    return s ? TUR_ATOMIC_LOAD_INT(&s->cancel_requested, __ATOMIC_ACQUIRE) : 0;
}

/* TC0: cancel action -- longjmp into cancel guard if active, else exit thread */
void tur_thread_do_cancel(void) {
    if (tur_cancel_jmpbuf_valid) {
        tur_cancel_jmpbuf_valid = 0;
        TUR_LONGJMP(tur_cancel_jmpbuf);
    }
    /* No cancel guard -- exit the thread cleanly without panicking. */
    pthread_exit(NULL);
}

void tur_fiber_shim(uint32_t hi, uint32_t lo) {
    FiberBlock *f = (FiberBlock *)(((uintptr_t)hi << 32) | (uintptr_t)(uint32_t)lo);
    void *task_group = f->task_group;
    if (task_group) {
        /* D1: save the enclosing catch-unwind handler chain and run the
         * fiber with an empty chain so an outer boundary does not catch a
         * panic that belongs to this fiber (the fiber uses its own
         * panic_jmpbuf); restore the caller's chain on both exit paths. */
        tur_handler_node *prev_chain = tur_handler_chain;
        tur_handler_chain = NULL;
        /* Set up per-fiber panic handler */
        if (TUR_SETJMP(f->panic_jmpbuf) == 0) {
            f->panic_jmpbuf_valid = 1;
            tur_current_fiber = f;
            f->entry_fn();
            tur_current_fiber = NULL;
            f->panic_jmpbuf_valid = 0;
            if (global_panic_payload) {
                panic_payload_free(global_panic_payload);
                global_panic_payload = NULL;
            }
            /* Restore the caller's catch-unwind handler chain */
            tur_handler_chain = prev_chain;
        } else {
            /* Panic caught - auto-cancel task group (TG-004-3) */
            f->panic_jmpbuf_valid = 0;
            tur_current_fiber = NULL;
            if (global_panic_payload) {
                typedef struct TaskGroupBlock { pthread_mutex_t lock; pthread_cond_t done_cond; int64_t task_count; int64_t completed_count; bool cancelled; bool done; int64_t cancel_reason; } TaskGroupBlock;
                TaskGroupBlock *g = (TaskGroupBlock *)task_group;
                pthread_mutex_lock(&g->lock);
                g->cancelled = true;
                g->done = true;
                g->cancel_reason = 1; /* panic reason (TG-004-2) */
                pthread_cond_broadcast(&g->done_cond);
                pthread_mutex_unlock(&g->lock);
                tur_fiber_set_cancelled(true);
                panic_payload_free(global_panic_payload);
                global_panic_payload = NULL;
            }
            /* Restore the caller's catch-unwind handler chain */
            tur_handler_chain = prev_chain;
        }
    } else {
        /* No task group, just run the function normally */
        f->entry_fn();
    }
    f->done = 1;
    if (task_group) tur_task_group_notify_done(task_group);
    swapcontext(&f->ctx, &f->caller_ctx);
    abort();
}

FiberBlock *tur_fiber_block_new(void (*fn)(void), size_t stack_size) {
    if (!stack_size) stack_size = 1024 * 1024;
#if defined(__APPLE__)
    if (sizeof(ucontext_t) <= sizeof(*((ucontext_t *)0)->uc_mcontext)) {
        fprintf(stderr, "fiber: ucontext_t has no room for its machine context (a header defined it before <ucontext.h> under _XOPEN_SOURCE)\n");
        abort();
    }
#endif
    FiberBlock *f = (FiberBlock *)calloc(1, sizeof(FiberBlock));
    if (!f) { fprintf(stderr, "fiber: oom\n"); abort(); }
    f->stack = (char *)malloc(stack_size);
    if (!f->stack) { free(f); abort(); }
    f->stack_size = stack_size; f->entry_fn = fn; f->done = 0;
    f->migration_safe = true;
    getcontext(&f->ctx);
    f->ctx.uc_stack.ss_sp = f->stack;
    f->ctx.uc_stack.ss_size = stack_size;
    f->ctx.uc_link = NULL;
    uintptr_t _fp = (uintptr_t)f;
    uint32_t _hi = (uint32_t)(_fp >> 32);
    uint32_t _lo = (uint32_t)(_fp & 0xFFFFFFFFU);
    makecontext(&f->ctx, (void(*)(void))tur_fiber_shim, 2, _hi, _lo);
    return f;
}

int64_t tur_fiber_block_resume(FiberBlock *f, int64_t arg) {
    if (!f || f->done) return f ? f->result : 0;
    if (f->cancelled) { f->done = 1; return 0; }
    if (f->task_group) {
        typedef struct TaskGroupBlock { pthread_mutex_t lock; pthread_cond_t done_cond; int64_t task_count; int64_t completed_count; bool cancelled; bool done; int64_t cancel_reason; } TaskGroupBlock;
        if (((TaskGroupBlock *)f->task_group)->cancelled) { f->cancelled = 1; f->done = 1; return 0; }
    }
    FiberBlock *_prev = tur_current_fiber;
    tur_current_fiber = f;
    f->arg = arg;
    tur_jmp_buf *_dk_save = g_dk_driver;
    void **_dk_rv = __dk_reap_v; unsigned char *_dk_rk = __dk_reap_kind;
    size_t _dk_rn = __dk_reap_n, _dk_rc = __dk_reap_cap; int _dk_rd = __dk_entry_depth;
    __dk_reap_v = f->dk_reap_v; __dk_reap_kind = f->dk_reap_kind;
    __dk_reap_n = f->dk_reap_n; __dk_reap_cap = f->dk_reap_cap; __dk_entry_depth = f->dk_entry_depth;
    tur_escape_cont **_esc_v = tur_escape_live; int _esc_n = tur_escape_live_n, _esc_c = tur_escape_live_cap;
    tur_escape_live = (tur_escape_cont **)f->esc_live; tur_escape_live_n = f->esc_live_n; tur_escape_live_cap = f->esc_live_cap;
    tur_r7rs_dynenv _r7dyn = tur_r7rs_dyn;
    memcpy(&tur_r7rs_dyn, f->r7dyn, sizeof tur_r7rs_dyn);
    TUR_GC_FIBER_ENTER((void *)&_dk_save);
    swapcontext(&f->caller_ctx, &f->ctx);
    TUR_GC_FIBER_LEAVE();
    f->dk_reap_v = __dk_reap_v; f->dk_reap_kind = __dk_reap_kind;
    f->dk_reap_n = __dk_reap_n; f->dk_reap_cap = __dk_reap_cap; f->dk_entry_depth = __dk_entry_depth;
    __dk_reap_v = _dk_rv; __dk_reap_kind = _dk_rk;
    __dk_reap_n = _dk_rn; __dk_reap_cap = _dk_rc; __dk_entry_depth = _dk_rd;
    f->esc_live = (void *)tur_escape_live; f->esc_live_n = tur_escape_live_n; f->esc_live_cap = tur_escape_live_cap;
    tur_escape_live = _esc_v; tur_escape_live_n = _esc_n; tur_escape_live_cap = _esc_c;
    memcpy(f->r7dyn, &tur_r7rs_dyn, sizeof f->r7dyn);
    tur_r7rs_dyn = _r7dyn;
    g_dk_driver = _dk_save;
    tur_current_fiber = _prev;
    return f->result;
}

void tur_fiber_block_yield(int64_t value) {
    FiberBlock *f = tur_current_fiber;
    if (!f) { fprintf(stderr, "fiber-yield: not in fiber\n"); abort(); }
    f->result = value;
    swapcontext(&f->ctx, &f->caller_ctx);
}

typedef struct FiberLocalEntry FiberLocalEntry;
struct FiberLocalEntry {
    int64_t key;
    int64_t value;
    FiberLocalEntry *next;
};

void tur_fiber_local_free(FiberBlock *f) {
    FiberLocalEntry *e = (FiberLocalEntry *)f->fiber_local;
    while (e) { FiberLocalEntry *n = e->next; free(e); e = n; }
}

int64_t tur_fiber_local_get(FiberBlock *f, int64_t key) {
    FiberLocalEntry *e = (FiberLocalEntry *)f->fiber_local;
    while (e) { if (e->key == key) return e->value; e = e->next; }
    return 0;
}

void tur_fiber_local_set(FiberBlock *f, int64_t key, int64_t value) {
    FiberLocalEntry *e = (FiberLocalEntry *)f->fiber_local;
    while (e) { if (e->key == key) { e->value = value; return; } e = e->next; }
    FiberLocalEntry *n = (FiberLocalEntry *)malloc(sizeof(FiberLocalEntry));
    if (!n) { fprintf(stderr, "fiber-local: oom\n"); abort(); }
    n->key = key; n->value = value;
    n->next = (FiberLocalEntry *)f->fiber_local;
    f->fiber_local = (void *)n;
}

void tur_fiber_block_free(FiberBlock *f) {
    if (!f) return;
    tur_fiber_local_free(f);
    free(f->stack); free(f);
}

bool tur_fiber_cancelled(void) {
    return tur_fiber_cancelled_flag;
}

void tur_fiber_set_cancelled(bool c) {
    tur_fiber_cancelled_flag = c;
}

void tur_task_group_notify_done(void *task_group) {
    if (!task_group) return;
    typedef struct TaskGroupBlock {
        pthread_mutex_t lock;
        pthread_cond_t done_cond;
        int64_t task_count;
        int64_t completed_count;
        bool cancelled;
        bool done;
        int64_t cancel_reason;
    } TaskGroupBlock;
    TaskGroupBlock *g = (TaskGroupBlock *)task_group;
    pthread_mutex_lock(&g->lock);
    g->completed_count++;
    if (g->completed_count >= g->task_count) {
        g->done = true;
        pthread_cond_broadcast(&g->done_cond);
    }
    pthread_mutex_unlock(&g->lock);
}

int64_t tur_monotonic_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000000000LL + (int64_t)ts.tv_nsec;
}

