typedef struct TurScheduler TurScheduler;
struct TurScheduler {
    FiberBlock **run_queue;
    int64_t run_queue_cap;
    int64_t run_queue_len;
    int64_t run_queue_head;
    int64_t run_queue_tail;
    FiberBlock *current_fiber;
    bool running;
};

TurScheduler *tur_scheduler = NULL;

TurScheduler *tur_scheduler_new(void) {
    TurScheduler *s = (TurScheduler *)calloc(1, sizeof(TurScheduler));
    if (!s) { fprintf(stderr, "scheduler: oom\n"); abort(); }
    s->run_queue_cap = 64;
    s->run_queue = (FiberBlock **)malloc(sizeof(FiberBlock *) * (size_t)s->run_queue_cap);
    if (!s->run_queue) { free(s); fprintf(stderr, "scheduler: queue oom\n"); abort(); }
    s->run_queue_len = 0;
    s->run_queue_head = 0;
    s->run_queue_tail = 0;
    s->current_fiber = NULL;
    s->running = false;
    return s;
}

TurScheduler *tur_scheduler_current(void) {
    return tur_scheduler;
}

void tur_scheduler_enqueue(TurScheduler *s, FiberBlock *f) {
    if (s->run_queue_len >= s->run_queue_cap) {
        int64_t new_cap = s->run_queue_cap * 2;
        FiberBlock **new_q = (FiberBlock **)malloc(sizeof(FiberBlock *) * (size_t)new_cap);
        if (!new_q) { fprintf(stderr, "scheduler: grow oom\n"); abort(); }
        for (int64_t i = 0; i < s->run_queue_len; i++)
            new_q[i] = s->run_queue[(s->run_queue_head + i) % s->run_queue_cap];
        free(s->run_queue);
        s->run_queue = new_q;
        s->run_queue_cap = new_cap;
        s->run_queue_head = 0;
        s->run_queue_tail = s->run_queue_len;
    }
    s->run_queue[s->run_queue_tail] = f;
    s->run_queue_tail = (s->run_queue_tail + 1) % s->run_queue_cap;
    s->run_queue_len++;
}

FiberBlock *tur_scheduler_dequeue(TurScheduler *s) {
    if (s->run_queue_len == 0) return NULL;
    FiberBlock *f = s->run_queue[s->run_queue_head];
    s->run_queue_head = (s->run_queue_head + 1) % s->run_queue_cap;
    s->run_queue_len--;
    return f;
}

void tur_scheduler_spawn(TurScheduler *s, FiberBlock *f) {
    tur_scheduler_enqueue(s, f);
}

void tur_scheduler_run(TurScheduler *s) {
    s->running = true;
    while (s->running) {
        /* Phase T24: tick timers and poll IO before dequeuing */
        tur_tick_timers();
        tur_poll_io(0);
        FiberBlock *f = tur_scheduler_dequeue(s);
        if (!f) {
            if (!tur_has_pending_timers() && !tur_has_pending_io()) break;
            int64_t sleep_us = tur_next_timer_wait_us();
            if (sleep_us < 0) sleep_us = 1000;
            if (tur_has_pending_io()) tur_poll_io(sleep_us);
            else { struct timespec ts = {0, sleep_us * 1000}; nanosleep(&ts, NULL); }
            continue;
        }
        s->current_fiber = f;
        tur_fiber_block_resume(f, 0);
        s->current_fiber = NULL;
        if (!f->done && !f->parked) tur_scheduler_enqueue(s, f);
    }
    s->running = false;
}

void tur_scheduler_run_to_completion(TurScheduler *s) {
    s->running = true;
    while (s->running) {
        tur_tick_timers();
        tur_poll_io(0);
        FiberBlock *f = tur_scheduler_dequeue(s);
        if (f) {
            s->current_fiber = f;
            tur_fiber_block_resume(f, 0);
            s->current_fiber = NULL;
            if (!f->done && !f->parked) tur_scheduler_enqueue(s, f);
        } else {
            if (!tur_has_pending_timers() && !tur_has_pending_io()) break;
            int64_t sleep_us = tur_next_timer_wait_us();
            if (sleep_us < 0) sleep_us = 1000;
            if (tur_has_pending_io()) tur_poll_io(sleep_us);
            else { struct timespec ts = {0, sleep_us * 1000}; nanosleep(&ts, NULL); }
        }
    }
    s->running = false;
}

void tur_scheduler_yield(void) {
    tur_fiber_block_yield(0);
}

void tur_scheduler_park(void) {
    if (tur_current_fiber) tur_current_fiber->parked = 1;
    tur_fiber_block_yield(0);
}

void tur_scheduler_unpark(FiberBlock *f) {
    if (!f) return;
    f->parked = 0;
    if (tur_scheduler) tur_scheduler_enqueue(tur_scheduler, f);
}

void tur_scheduler_unpark_cb(void *f) {
    tur_scheduler_unpark((FiberBlock *)f);
}

TurTimerWheel *tur_timer_wheel_new(void) {
    TurTimerWheel *w = (TurTimerWheel *)calloc(1, sizeof(TurTimerWheel));
    if (!w) { fprintf(stderr, "timer wheel: oom\n"); abort(); }
    w->cap = 64;
    w->heap = (TurTimerEntry **)malloc(sizeof(TurTimerEntry *) * (size_t)w->cap);
    if (!w->heap) { free(w); fprintf(stderr, "timer wheel: heap oom\n"); abort(); }
    w->len = 0;
    w->next_id = 1;
    return w;
}

void tur_timer_heap_sift_up(TurTimerWheel *w, int64_t idx) {
    while (idx > 0) {
        int64_t parent = (idx - 1) / 2;
        if (w->heap[parent]->deadline_ns <= w->heap[idx]->deadline_ns) break;
        TurTimerEntry *tmp = w->heap[parent];
        w->heap[parent] = w->heap[idx];
        w->heap[idx] = tmp;
        idx = parent;
    }
}

void tur_timer_heap_sift_down(TurTimerWheel *w, int64_t idx) {
    while (1) {
        int64_t smallest = idx;
        int64_t left = 2 * idx + 1;
        int64_t right = 2 * idx + 2;
        if (left < w->len && w->heap[left]->deadline_ns < w->heap[smallest]->deadline_ns)
            smallest = left;
        if (right < w->len && w->heap[right]->deadline_ns < w->heap[smallest]->deadline_ns)
            smallest = right;
        if (smallest == idx) break;
        TurTimerEntry *tmp = w->heap[smallest];
        w->heap[smallest] = w->heap[idx];
        w->heap[idx] = tmp;
        idx = smallest;
    }
}

int64_t tur_timer_wheel_insert(TurTimerWheel *w, int64_t deadline_ns,
                                       void (*cb)(void *), void *arg) {
    if (w->len >= w->cap) {
        int64_t new_cap = w->cap * 2;
        TurTimerEntry **nh = (TurTimerEntry **)malloc(sizeof(TurTimerEntry *) * (size_t)new_cap);
        if (!nh) { fprintf(stderr, "timer wheel: grow oom\n"); abort(); }
        for (int64_t i = 0; i < w->len; i++) nh[i] = w->heap[i];
        free(w->heap);
        w->heap = nh;
        w->cap = new_cap;
    }
    TurTimerEntry *e = (TurTimerEntry *)malloc(sizeof(TurTimerEntry));
    if (!e) { fprintf(stderr, "timer entry: oom\n"); abort(); }
    e->deadline_ns = deadline_ns;
    e->callback = cb;
    e->arg = arg;
    e->id = w->next_id++;
    e->cancelled = false;
    w->heap[w->len] = e;
    tur_timer_heap_sift_up(w, w->len);
    w->len++;
    return e->id;
}

void tur_timer_wheel_cancel(TurTimerWheel *w, int64_t id) {
    for (int64_t i = 0; i < w->len; i++) {
        if (w->heap[i]->id == id) { w->heap[i]->cancelled = true; return; }
    }
}

void tur_timer_wheel_tick(TurTimerWheel *w) {
    int64_t now = tur_monotonic_ns();
    while (w->len > 0 && w->heap[0]->deadline_ns <= now) {
        TurTimerEntry *e = w->heap[0];
        w->len--;
        if (w->len > 0) {
            w->heap[0] = w->heap[w->len];
            tur_timer_heap_sift_down(w, 0);
        }
        if (!e->cancelled) e->callback(e->arg);
        free(e);
    }
}

int64_t tur_timer_wheel_next_deadline_ns(TurTimerWheel *w) {
    while (w->len > 0 && w->heap[0]->cancelled) {
        TurTimerEntry *e = w->heap[0];
        w->len--;
        if (w->len > 0) {
            w->heap[0] = w->heap[w->len];
            tur_timer_heap_sift_down(w, 0);
        }
        free(e);
    }
    if (w->len == 0) return -1;
    return w->heap[0]->deadline_ns;
}

void tur_scheduler_timeout(int64_t ms, void (*callback)(void *arg), void *arg) {
    if (!tur_global_timers) tur_global_timers = tur_timer_wheel_new();
    int64_t deadline = tur_monotonic_ns() + ms * 1000000LL;
    tur_timer_wheel_insert(tur_global_timers, deadline, callback, arg);
}

void tur_io_register(int fd, int events, FiberBlock *fiber) {
    TurIOWaiter *w = (TurIOWaiter *)malloc(sizeof(TurIOWaiter));
    if (!w) { fprintf(stderr, "io waiter: oom\n"); abort(); }
    w->fd = fd;
    w->events = events;
    w->fiber = fiber;
    w->next = tur_io_waiters;
    tur_io_waiters = w;
}

void tur_io_unregister(int fd) {
    TurIOWaiter **pp = &tur_io_waiters;
    while (*pp) {
        if ((*pp)->fd == fd) {
            TurIOWaiter *tmp = *pp;
            *pp = tmp->next;
            free(tmp);
            return;
        }
        pp = &(*pp)->next;
    }
}

void tur_io_poll(int64_t timeout_us) {
    if (!tur_io_waiters) return;
    fd_set rfds, wfds;
    FD_ZERO(&rfds);
    FD_ZERO(&wfds);
    int maxfd = -1;
    for (TurIOWaiter *w = tur_io_waiters; w; w = w->next) {
        if (w->events & TUR_IO_READ)  FD_SET(w->fd, &rfds);
        if (w->events & TUR_IO_WRITE) FD_SET(w->fd, &wfds);
        if (w->fd > maxfd) maxfd = w->fd;
    }
    struct timeval tv;
    tv.tv_sec = (long)(timeout_us / 1000000);
    tv.tv_usec = (long)(timeout_us % 1000000);
    int ret = select(maxfd + 1, &rfds, &wfds, NULL, &tv);
    if (ret <= 0) return;
    TurIOWaiter **pp = &tur_io_waiters;
    while (*pp) {
        TurIOWaiter *w = *pp;
        bool ready = false;
        if ((w->events & TUR_IO_READ)  && FD_ISSET(w->fd, &rfds))  ready = true;
        if ((w->events & TUR_IO_WRITE) && FD_ISSET(w->fd, &wfds)) ready = true;
        if (ready) {
            FiberBlock *f = w->fiber;
            *pp = w->next;
            free(w);
            tur_scheduler_unpark(f);
        } else {
            pp = &w->next;
        }
    }
}

void tur_tick_timers(void) {
    if (tur_global_timers) tur_timer_wheel_tick(tur_global_timers);
}

void tur_poll_io(int64_t timeout_us) {
    if (tur_io_waiters) tur_io_poll(timeout_us);
}

bool tur_has_pending_timers(void) {
    return tur_global_timers && tur_global_timers->len > 0;
}

bool tur_has_pending_io(void) {
    return tur_io_waiters != NULL;
}

int64_t tur_next_timer_wait_us(void) {
    if (!tur_global_timers || tur_global_timers->len == 0) return -1;
    int64_t next = tur_timer_wheel_next_deadline_ns(tur_global_timers);
    if (next < 0) return -1;
    int64_t diff = (next - tur_monotonic_ns()) / 1000;
    return diff > 0 ? diff : 0;
}

#ifdef __clang__
#pragma clang diagnostic pop
#endif

void tur_scheduler_run_one(TurScheduler *s) {
    FiberBlock *f = tur_scheduler_dequeue(s);
    if (!f) { return; }
    s->current_fiber = f;
    tur_fiber_block_resume(f, 0);
    s->current_fiber = NULL;
    if (!f->done && !f->parked) tur_scheduler_enqueue(s, f);
}

/* Phase T23: Multi-threaded scheduler */
typedef struct TurSchedulerMT {
    pthread_t       *threads;
    size_t           n_threads;
    pthread_mutex_t  lock;
    pthread_cond_t   cond;
    FiberBlock     **queue;
    size_t           qhead;
    size_t           qtail;
    size_t           qcap;
    bool             running;
    int              active;
} TurSchedulerMT;

#if defined(__GNUC__) || defined(__clang__)
extern void ** tur_tls_current_scheduler_mt_ptr(void);
#define tur_current_scheduler_mt (*(TurSchedulerMT * *)tur_tls_current_scheduler_mt_ptr())

#else
extern void ** tur_tls_current_scheduler_mt_ptr(void);
#define tur_current_scheduler_mt (*(TurSchedulerMT **)tur_tls_current_scheduler_mt_ptr())
#endif
void tur_scheduler_mt_enqueue_locked(TurSchedulerMT *s, FiberBlock *f) {
    if (((s->qtail + 1) % s->qcap) == s->qhead) {
        size_t ncap = s->qcap * 2;
        FiberBlock **nq = (FiberBlock **)calloc(ncap, sizeof(FiberBlock *));
        size_t k = 0;
        for (size_t i = s->qhead; i != s->qtail; i = (i + 1) % s->qcap) nq[k++] = s->queue[i];
        free(s->queue);
        s->queue = nq; s->qcap = ncap; s->qhead = 0; s->qtail = k;
    }
    s->queue[s->qtail] = f;
    s->qtail = (s->qtail + 1) % s->qcap;
}

void *tur_scheduler_mt_worker(void *arg) {
    TurSchedulerMT *s = (TurSchedulerMT *)arg;
    tur_current_scheduler_mt = s;
    for (;;) {
        pthread_mutex_lock(&s->lock);
        while (s->running && s->qhead == s->qtail) {
            pthread_cond_wait(&s->cond, &s->lock);
        }
        if (!s->running && s->qhead == s->qtail) {
            pthread_mutex_unlock(&s->lock);
            break;
        }
        FiberBlock *f = s->queue[s->qhead];
        s->qhead = (s->qhead + 1) % s->qcap;
        s->active++;
        pthread_mutex_unlock(&s->lock);
        tur_fiber_block_resume(f, 0);
        pthread_mutex_lock(&s->lock);
        s->active--;
        if (!f->done && !f->parked) tur_scheduler_mt_enqueue_locked(s, f);
        pthread_cond_broadcast(&s->cond);
        pthread_mutex_unlock(&s->lock);
    }
    return NULL;
}

TurSchedulerMT *tur_scheduler_mt_new(size_t n_threads) {
    if (n_threads == 0) n_threads = 1;
    TurSchedulerMT *s = (TurSchedulerMT *)calloc(1, sizeof(TurSchedulerMT));
    if (!s) return NULL;
    pthread_mutex_init(&s->lock, NULL);
    pthread_cond_init(&s->cond, NULL);
    s->qcap = 32;
    s->queue = (FiberBlock **)calloc(s->qcap, sizeof(FiberBlock *));
    s->n_threads = n_threads;
    s->threads = (pthread_t *)calloc(n_threads, sizeof(pthread_t));
    s->running = true;
    for (size_t i = 0; i < n_threads; i++) {
        pthread_create(&s->threads[i], NULL, tur_scheduler_mt_worker, s);
    }
    return s;
}

void tur_scheduler_mt_free(TurSchedulerMT *s) {
    if (!s) return;
    pthread_mutex_lock(&s->lock);
    /* Drain: wait until queue is empty and no fiber is active */
    while (s->qhead != s->qtail || s->active > 0) {
        pthread_cond_wait(&s->cond, &s->lock);
    }
    s->running = false;
    pthread_cond_broadcast(&s->cond);
    pthread_mutex_unlock(&s->lock);
    for (size_t i = 0; i < s->n_threads; i++) pthread_join(s->threads[i], NULL);
    pthread_mutex_destroy(&s->lock);
    pthread_cond_destroy(&s->cond);
    free(s->queue); free(s->threads); free(s);
}

void tur_scheduler_mt_spawn(TurSchedulerMT *s, FiberBlock *f) {
    if (!s || !f) return;
    pthread_mutex_lock(&s->lock);
    tur_scheduler_mt_enqueue_locked(s, f);
    pthread_cond_signal(&s->cond);
    pthread_mutex_unlock(&s->lock);
}

void tur_scheduler_mt_run(TurSchedulerMT *s) {
    /* Worker threads run automatically; this is a no-op for the
     * shared-queue impl.  Kept for API compatibility. */
    (void)s;
}

int64_t tur_scheduler_mt_thread_id(void) {
    return (int64_t)(uintptr_t)pthread_self();
}

void tur_scheduler_mt_set_current(TurSchedulerMT *s) {
    tur_current_scheduler_mt = s;
}

TurSchedulerMT *tur_scheduler_mt_current(void) {
    return tur_current_scheduler_mt;
}

void tur_scheduler_mt_yield(void) {
    /* Cooperative yield: re-enqueues current fiber via the worker loop. */
    tur_fiber_block_yield(0);
}

void tur_scheduler_mt_park(void) {
    FiberBlock *f = tur_current_fiber;
    if (f) f->parked = 1;
    tur_fiber_block_yield(0);
}

void tur_scheduler_mt_unpark(FiberBlock *f) {
    TurSchedulerMT *s = tur_current_scheduler_mt;
    if (!f || !s) return;
    f->parked = 0;
    pthread_mutex_lock(&s->lock);
    tur_scheduler_mt_enqueue_locked(s, f);
    pthread_cond_signal(&s->cond);
    pthread_mutex_unlock(&s->lock);
}

/* Phase T21-F: async/await runtime - fiber-based Futures */
typedef enum { FUTURE_PENDING, FUTURE_FULFILLED, FUTURE_REJECTED } TurFutureStatus;

typedef struct TurFuture TurFuture;
struct TurFuture {
    TurFutureStatus status;
    int64_t value;
    const char *error;  /* NULL if no error */
    FiberBlock *fiber;  /* The fiber running the async task */
    struct { void (*fn)(TurFuture *, int64_t); void *env; } on_complete;
    void *thread;       /* pthread_t * of a thread-backed async; joined by await */
};

/* Create a new pending future */
TurFuture *tur_future_new(void) {
    TurFuture *f = (TurFuture *)calloc(1, sizeof(TurFuture));
    if (!f) { fprintf(stderr, "future: oom\n"); abort(); }
    f->status = FUTURE_PENDING;
    f->fiber = NULL;
    f->on_complete.fn = NULL;
    return f;
}

/* Fulfill a future with a value */
void tur_future_fulfill(TurFuture *f, int64_t value) {
    if (!f || f->status != FUTURE_PENDING) return;
    f->status = FUTURE_FULFILLED;
    f->value = value;
    if (f->on_complete.fn) f->on_complete.fn(f, value);
}

/* Reject a future with an error message */
void tur_future_reject(TurFuture *f, const char *error) {
    if (!f || f->status != FUTURE_PENDING) return;
    f->status = FUTURE_REJECTED;
    f->error = error;
}

/* Check if future is done (fulfilled or rejected) */
int tur_future_done(TurFuture *f) {
    return f && (f->status == FUTURE_FULFILLED || f->status == FUTURE_REJECTED);
}

/* Get future value (only valid if fulfilled) */
int64_t tur_future_get(TurFuture *f) {
    if (!f || f->status != FUTURE_FULFILLED) return 0;
    return f->value;
}

typedef struct { DK *subk; TurFuture *outer; __dk_reap_seg seg; int depth; } TurAsyncPark;

int tur_async_suspended = 0;      /* set by __tur_await_body when it parks */
TurAsyncPark *tur_async_pending_park = NULL;  /* the park the last suspend created */

__attribute__((unused)) void __dk_entry_leave(DK *root, size_t mark) {
    if (tur_async_suspended) {
        TurAsyncPark *p = tur_async_pending_park;
        if (!p || p->depth != __dk_entry_depth) return;
        __dk_reap_seg_take(&p->seg, mark);
        __dk_reap_seg_add(&p->seg, root, 1);
        p->depth = -1;  /* owned now: an outer exit is not its owner */
        --__dk_entry_depth;
        return;
    }
    dk_free(root);
    if (--__dk_entry_depth == 0) __dk_reap_run(); else __dk_reap_drop_to(mark);
}

__attribute__((unused)) int64_t __dk_enter0(int64_t (*body)(DK *), void *out, size_t out_size) {
    __dk_entry_depth++;
    size_t __dk_reap_mark = __dk_reap_n;
    DK *__root = dk_prompt(DK_ROOT_TAG, dk_done());
    int64_t __r;
    tur_jmp_buf __dkjb; tur_jmp_buf *__dksave = g_dk_driver; g_dk_driver = &__dkjb;
    if (TUR_SETJMP(__dkjb) == 0) { __r = body(__root); }
    else { __r = __dk_drive_after(); }
    g_dk_driver = __dksave;
    if (out) { if (__r) memcpy(out, (const void *)(intptr_t)__r, out_size); else memset(out, 0, out_size); }
    __dk_entry_leave(__root, __dk_reap_mark);
    return __r;
}

int tur_async_reject_if_panicking(TurFuture *future) {
    if (!tur_panicking) return 0;
    tur_panicking = 0; tur_panic_in_progress = 0;
    tur_panic_payload *__p = global_panic_payload;
    global_panic_payload = NULL;
    const char *__msg = "panic";
    if (__p) {
        if (__p->type_tag == 5 && __p->value) {
            __msg = (const char *)__p->value;
            __p->owns_value = 0;  /* the future owns it now */
        }
        panic_payload_free(__p);
    }
    tur_future_reject(future, __msg);
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    return 1;
}

TurFuture *tur_async_fiber(int64_t (*fn)(void)) {
    TurFuture *future = tur_future_new();
    if (!tur_scheduler) {
        /* AW-005: Initialize scheduler on first use */
        tur_scheduler = tur_scheduler_new();
    }
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    tur_handler_node __node; __node.parent = tur_handler_chain;
    tur_handler_chain = &__node;
    int64_t result = fn();
    tur_handler_chain = __node.parent;
    if (tur_async_reject_if_panicking(future)) return future;
    if (tur_async_suspended && tur_async_pending_park) {
        /* body parked on a pending await: leave `future` pending; the parked
         * resume fulfills it when the awaited future completes. */
        tur_async_pending_park->outer = future;
    } else {
        tur_future_fulfill(future, result);
    }
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    return future;
}

TurFuture *tur_async_fiber_closure(void *clos) {
    TurFuture *future = tur_future_new();
    if (!tur_scheduler) {
        tur_scheduler = tur_scheduler_new();
    }
    int64_t (*__fn)(void *) = *(int64_t (**)(void *))clos;
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    tur_handler_node __node; __node.parent = tur_handler_chain;
    tur_handler_chain = &__node;
    int64_t result = __fn(clos);
    tur_handler_chain = __node.parent;
    if (tur_async_reject_if_panicking(future)) return future;
    if (tur_async_suspended && tur_async_pending_park) {
        tur_async_pending_park->outer = future;
    } else {
        tur_future_fulfill(future, result);
    }
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    return future;
}

TurFuture *tur_async_fiber_via(int64_t (*wrap)(void *), void *env) {
    TurFuture *future = tur_future_new();
    if (!tur_scheduler) {
        tur_scheduler = tur_scheduler_new();
    }
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    tur_handler_node __node; __node.parent = tur_handler_chain;
    tur_handler_chain = &__node;
    int64_t result = wrap(env);
    tur_handler_chain = __node.parent;
    if (tur_async_reject_if_panicking(future)) return future;
    if (tur_async_suspended && tur_async_pending_park) {
        tur_async_pending_park->outer = future;
    } else {
        tur_future_fulfill(future, result);
    }
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    return future;
}

typedef struct { int64_t (*call)(void *); void *env; TurFuture *future; } TurAsyncThreadArg;

int64_t __tur_async_call_box(void *clos) {
    int64_t (*__fn)(void *) = *(int64_t (**)(void *))clos;
    return __fn(clos);
}

void *tur_async_thread_main(void *p) {
    TurAsyncThreadArg *a = (TurAsyncThreadArg *)p;
    TurFuture *future = a->future;
    tur_handler_node __node; __node.parent = tur_handler_chain;
    tur_handler_chain = &__node;
    int64_t result = a->call(a->env);
    tur_handler_chain = __node.parent;
    free(a);
    if (!tur_async_reject_if_panicking(future)) {
        future->value = result;
        future->status = FUTURE_FULFILLED;
    }
    return NULL;
}

TurFuture *tur_async_thread_via(int64_t (*call)(void *), void *env) {
    TurFuture *future = tur_future_new();
    if (!tur_scheduler) tur_scheduler = tur_scheduler_new();
    TurAsyncThreadArg *a = (TurAsyncThreadArg *)malloc(sizeof(TurAsyncThreadArg));
    pthread_t *tid = (pthread_t *)malloc(sizeof(pthread_t));
    if (!a || !tid) { fprintf(stderr, "async: out of memory\n"); abort(); }
    a->call = call; a->env = env; a->future = future;
    if (pthread_create(tid, NULL, tur_async_thread_main, a) != 0) {
        fprintf(stderr, "async: pthread_create failed\n");
        abort();
    }
    future->thread = (void *)tid;
    return future;
}

void tur_future_join_thread(TurFuture *f) {
    if (!f || !f->thread) return;
    pthread_join(*(pthread_t *)f->thread, NULL);
    free(f->thread);
    f->thread = NULL;
}

/* AW-004: await lowering with shift + scheduler callback */
int64_t tur_await_future(TurFuture *f) {
    if (!f) { fprintf(stderr, "await: null future\n"); abort(); }
    tur_future_join_thread(f);
    if (tur_future_done(f)) {
        if (f->status == FUTURE_REJECTED) {
            /* Re-raise the task's panic at the point that demanded the
             * result: with a catch-unwind in scope this is catchable, and
             * with none tur_panic prints the task's message and aborts. */
            tur_panic(f->error ? f->error : "async task panicked");
            return 0;
        }
        return f->value;
    }
    /* Future not ready */
    if (!tur_current_fiber) {
        /* Not in a fiber - run the scheduler until future is done */
        if (!tur_scheduler) {
            fprintf(stderr, "await: no scheduler and not in fiber\n");
            abort();
        }
        while (!tur_future_done(f)) {
            tur_scheduler_run_one(tur_scheduler);
        }
    } else {
        /* In a fiber - yield and let scheduler resume us */
        /* Register a callback to re-enqueue this fiber when future completes */
        f->on_complete.fn = (void (*)(TurFuture *, int64_t))tur_fiber_block_resume;
        f->on_complete.env = (void *)tur_current_fiber;
        tur_fiber_block_yield(0);
        /* When we resume, the future should be done */
        if (tur_future_done(f) && f->status == FUTURE_REJECTED) {
            tur_panic(f->error ? f->error : "async task panicked");
            return 0;
        }
        return f->value;
    }
    if (f->status == FUTURE_REJECTED) {
        fprintf(stderr, "await: future rejected: %s\n", f->error ? f->error : "unknown");
        abort();
    }
    return f->value;
}

void __tur_async_resume(TurFuture *inner, int64_t value) {
    TurAsyncPark *rec = (TurAsyncPark *)inner->on_complete.env;
    tur_async_suspended = 0;
    tur_async_pending_park = NULL;
    __dk_entry_depth++;
    size_t __dk_reap_mark = __dk_reap_n;
    rec->subk->inplace_head = true;
    int64_t r = (int64_t)__dk_drive_bounded(rec->subk, (intptr_t)value);
    dk_free(rec->subk);
    if (tur_async_suspended && tur_async_pending_park) {
        /* re-parked on a further pending await: thread the outer future through */
        TurAsyncPark *np = tur_async_pending_park;
        np->outer = rec->outer;
        if (np->depth == __dk_entry_depth) {
            __dk_reap_seg_move(&np->seg, &rec->seg);
            __dk_reap_seg_take(&np->seg, __dk_reap_mark);
            np->depth = -1;
            --__dk_entry_depth;
        } else {
            __dk_reap_seg_give(&rec->seg);
        }
        tur_async_suspended = 0;
        tur_async_pending_park = NULL;
    } else {
        tur_async_suspended = 0;
        tur_async_pending_park = NULL;
        __dk_reap_seg_give(&rec->seg);
        if (--__dk_entry_depth == 0) __dk_reap_run(); else __dk_reap_drop_to(__dk_reap_mark);
        tur_future_fulfill(rec->outer, r);
    }
    free(rec);
}

__attribute__((unused)) int __tur_await_ready(void *fp) {
    TurFuture *f = (TurFuture *)fp;
    if (!f) return 0;
    tur_future_join_thread(f);
    if (tur_scheduler)
        while (!tur_future_done(f) && tur_scheduler->run_queue_len > 0)
            tur_scheduler_run_one(tur_scheduler);
    return f->status == FUTURE_FULFILLED;
}

__attribute__((unused)) intptr_t __tur_await_value(void *fp) {
    return (intptr_t)((TurFuture *)fp)->value;
}

__attribute__((unused)) int __tur_future_pending(void *fp) {
    return fp && ((TurFuture *)fp)->status == FUTURE_PENDING;
}

intptr_t __tur_await_body(intptr_t env, DK *subk) {
    TurFuture *f = (TurFuture *)(intptr_t)env;
    if (!f) { fprintf(stderr, "await: null future\n"); abort(); }
    tur_future_join_thread(f);
    if (tur_future_done(f)) {
        if (f->status == FUTURE_REJECTED) {
            /* Same re-raise as tur_await_future; the resumed continuation
             * sees tur_panicking and unwinds through its own checks. */
            tur_panic(f->error ? f->error : "async task panicked");
            return dk_invoke(subk, 0);
        }
        return dk_invoke(subk, f->value);
    }
    /* cps-async graduation: a pending future backed by a RUNNABLE scheduler
     * fiber (e.g. a fiber spawned via tur_scheduler_spawn, or a TaskGroup
     * child) completes only when the scheduler runs it.  Mirror
     * tur_await_future's non-fiber branch: drain runnable fibers until the
     * future resolves, then resume the captured continuation inline.  Bounded
     * by run_queue_len, so a future that can only complete asynchronously
     * (the deferred reactor / async-boundary park below) does not spin. */
    if (tur_scheduler) {
        while (!tur_future_done(f) && tur_scheduler->run_queue_len > 0) {
            tur_scheduler_run_one(tur_scheduler);
        }
        if (tur_future_done(f)) {
            if (f->status == FUTURE_REJECTED) {
                fprintf(stderr, "await: future rejected: %s\n", f->error ? f->error : "unknown");
                abort();
            }
            return dk_invoke(subk, f->value);
        }
    }
    /* pending: park a private copy of the captured continuation on on_complete */
    TurAsyncPark *rec = (TurAsyncPark *)calloc(1, sizeof(TurAsyncPark));
    if (!rec) { fprintf(stderr, "await: oom\n"); abort(); }
    rec->subk = dk_copy_range_owned(subk, NULL);
    rec->outer = NULL;  /* patched by the async boundary (tur_async_fiber) */
    rec->depth = __dk_entry_depth;  /* the entry whose root this shift reached */
    f->on_complete.fn = (void (*)(TurFuture *, int64_t))__tur_async_resume;
    f->on_complete.env = (void *)rec;
    tur_async_suspended = 1;
    tur_async_pending_park = rec;
    return 0;  /* dummy: the boundary reads tur_async_suspended, not this value */
}

void tur_future_free(TurFuture *f) {
    if (!f) return;
    free(f);
}

/* Backward compatibility: TurAsyncTask = TurFuture */
typedef TurFuture TurAsyncTask;

/* Phase SEL0: TurSelectWaiter -- select waiter for fair multi-channel blocking */
typedef struct TurSelectWaiter TurSelectWaiter;
struct TurSelectWaiter {
    pthread_mutex_t *wakeup_mutex;
    pthread_cond_t  *wakeup_cond;
    volatile int    *selected_idx;
    int              clause_idx;
    TurSelectWaiter *next;
};

/* Phase SEL0: signal the first unselected waiter in the list */
void tur_waiter_signal_one(void *waiter_list) {
    TurSelectWaiter *w = (TurSelectWaiter *)waiter_list;
    while (w) {
        int exp = -1;
        if (TUR_ATOMIC_CAS_INT(w->selected_idx, &exp, w->clause_idx,
                               __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {
            pthread_mutex_lock(w->wakeup_mutex);
            pthread_cond_signal(w->wakeup_cond);
            pthread_mutex_unlock(w->wakeup_mutex);
            return;
        }
        w = w->next;
    }
}

/* Phase SEL1: TurSelectClause -- clause descriptor for tur_select_blocking */
typedef struct { void *chan; int op; int64_t val; } TurSelectClause;

/* Phase SEL1: persistent xorshift32 PRNG for fair select */
volatile uint32_t __tur_xr_state = 1u;

/* Phase SEL1: tur_select_blocking -- block on all clauses; wake on first ready.
 * clauses: array of TurSelectClause (op 0=recv, 1=send)
 * n: number of clauses
 * has_default: 1 if a :default arm is present
 * Returns: index of the clause that fired, or -1 for default */
int tur_select_blocking(TurSelectClause *clauses, int n, int has_default) {
    typedef struct {
        pthread_mutex_t lock; pthread_cond_t not_full; pthread_cond_t not_empty;
        int64_t *buf; int64_t head; int64_t tail; int64_t count; int64_t cap;
        void *recv_waiters; void *send_waiters;
    } ChanBlock_;
    if (n <= 0) return -2;
    /* Phase 1: non-blocking scan -- try all clauses without blocking */
    /* Collect unique channels for lock ordering */
    ChanBlock_ *lock_order[64];
    int n_unique = 0;
    for (int i = 0; i < n && n_unique < 64; i++) {
        ChanBlock_ *ch = (ChanBlock_ *)clauses[i].chan;
        int found = 0;
        for (int j = 0; j < n_unique; j++) if (lock_order[j] == ch) { found = 1; break; }
        if (!found) lock_order[n_unique++] = ch;
    }
    /* Sort channels by address for deadlock-free locking order */
    for (int i = 0; i < n_unique - 1; i++)
        for (int j = i + 1; j < n_unique; j++)
            if ((uintptr_t)lock_order[i] > (uintptr_t)lock_order[j]) {
                ChanBlock_ *tmp = lock_order[i]; lock_order[i] = lock_order[j]; lock_order[j] = tmp;
            }
    /* Acquire all locks */
    for (int i = 0; i < n_unique; i++) pthread_mutex_lock(&lock_order[i]->lock);
    /* Final non-blocking scan under all locks */
    int ready[64]; int n_ready = 0;
    for (int i = 0; i < n; i++) {
        ChanBlock_ *ch = (ChanBlock_ *)clauses[i].chan;
        if (clauses[i].op == 0) { if (ch->count > 0) ready[n_ready++] = i; }
        else                   { if (ch->count < ch->cap) ready[n_ready++] = i; }
    }
    if (n_ready > 0) {
        /* Fair: pick uniformly at random among ready clauses.
         * Use a persistent xorshift32 state so repeated calls from the
         * same site (e.g. a TCO loop) don't always produce the same winner. */
        uint32_t xr = __tur_xr_state;
        xr ^= (uint32_t)(uintptr_t)clauses;
        if (!xr) xr = 0x9e3779b9u;
        xr ^= xr << 13; xr ^= xr >> 17; xr ^= xr << 5;
        __tur_xr_state = xr;
        int winner = ready[xr % (uint32_t)n_ready];
        ChanBlock_ *wch = (ChanBlock_ *)clauses[winner].chan;
        if (clauses[winner].op == 0) { /* recv */
            clauses[winner].val = wch->buf[wch->head];
            wch->head = (wch->head + 1) % wch->cap; wch->count--;
            pthread_cond_signal(&wch->not_full);
            tur_waiter_signal_one(wch->send_waiters);
        } else { /* send */
            wch->buf[wch->tail] = clauses[winner].val;
            wch->tail = (wch->tail + 1) % wch->cap; wch->count++;
            pthread_cond_signal(&wch->not_empty);
            tur_waiter_signal_one(wch->recv_waiters);
        }
        for (int i = 0; i < n_unique; i++) pthread_mutex_unlock(&lock_order[i]->lock);
        return winner;
    }
    /* Phase 2: default arm */
    if (has_default) {
        for (int i = 0; i < n_unique; i++) pthread_mutex_unlock(&lock_order[i]->lock);
        return -1;
    }
    /* Phase 3: register waiters and sleep until one fires */
    pthread_mutex_t wakeup_mutex;
    pthread_cond_t  wakeup_cond;
    pthread_mutex_init(&wakeup_mutex, NULL);
    pthread_cond_init(&wakeup_cond, NULL);
    volatile int selected_idx = -1;
    TurSelectWaiter waiters[64];
    int wn = n < 64 ? n : 64;
    for (int i = 0; i < wn; i++) {
        waiters[i].wakeup_mutex = &wakeup_mutex;
        waiters[i].wakeup_cond  = &wakeup_cond;
        waiters[i].selected_idx = &selected_idx;
        waiters[i].clause_idx   = i;
        ChanBlock_ *ch = (ChanBlock_ *)clauses[i].chan;
        if (clauses[i].op == 0) { /* recv waiter */
            waiters[i].next = (TurSelectWaiter *)ch->recv_waiters;
            ch->recv_waiters = &waiters[i];
        } else { /* send waiter */
            waiters[i].next = (TurSelectWaiter *)ch->send_waiters;
            ch->send_waiters = &waiters[i];
        }
    }
    /* Release all channel locks */
    for (int i = 0; i < n_unique; i++) pthread_mutex_unlock(&lock_order[i]->lock);
    /* Sleep until woken by a channel operation or cancelled (TC1) */
    pthread_mutex_lock(&wakeup_mutex);
    while (TUR_ATOMIC_LOAD_INT(&selected_idx, __ATOMIC_ACQUIRE) == -1) {
        if (tur_thread_cancel_requested()) {
            pthread_mutex_unlock(&wakeup_mutex);
            /* Deregister all waiters before cancelling */
            for (int __ci = 0; __ci < wn; __ci++) {
                ChanBlock_ *__cch = (ChanBlock_ *)clauses[__ci].chan;
                pthread_mutex_lock(&__cch->lock);
                if (clauses[__ci].op == 0) {
                    TurSelectWaiter **pp = (TurSelectWaiter **)&__cch->recv_waiters;
                    while (*pp && *pp != &waiters[__ci]) pp = &(*pp)->next;
                    if (*pp) *pp = (*pp)->next;
                } else {
                    TurSelectWaiter **pp = (TurSelectWaiter **)&__cch->send_waiters;
                    while (*pp && *pp != &waiters[__ci]) pp = &(*pp)->next;
                    if (*pp) *pp = (*pp)->next;
                }
                pthread_mutex_unlock(&__cch->lock);
            }
            pthread_mutex_destroy(&wakeup_mutex);
            pthread_cond_destroy(&wakeup_cond);
            tur_thread_do_cancel();
        }
        struct timespec __sel_ts;
        clock_gettime(CLOCK_REALTIME, &__sel_ts);
        long __sel_ns = __sel_ts.tv_nsec + 5000000L;
        __sel_ts.tv_sec += __sel_ns / 1000000000L;
        __sel_ts.tv_nsec = __sel_ns % 1000000000L;
        pthread_cond_timedwait(&wakeup_cond, &wakeup_mutex, &__sel_ts);
    }
    int winner = TUR_ATOMIC_LOAD_INT(&selected_idx, __ATOMIC_ACQUIRE);
    pthread_mutex_unlock(&wakeup_mutex);
    /* Deregister all waiters */
    for (int i = 0; i < wn; i++) {
        ChanBlock_ *ch = (ChanBlock_ *)clauses[i].chan;
        pthread_mutex_lock(&ch->lock);
        if (clauses[i].op == 0) {
            TurSelectWaiter **pp = (TurSelectWaiter **)&ch->recv_waiters;
            while (*pp && *pp != &waiters[i]) pp = &(*pp)->next;
            if (*pp) *pp = (*pp)->next;
        } else {
            TurSelectWaiter **pp = (TurSelectWaiter **)&ch->send_waiters;
            while (*pp && *pp != &waiters[i]) pp = &(*pp)->next;
            if (*pp) *pp = (*pp)->next;
        }
        pthread_mutex_unlock(&ch->lock);
    }
    /* Execute the winning clause */
    ChanBlock_ *wch = (ChanBlock_ *)clauses[winner].chan;
    pthread_mutex_lock(&wch->lock);
    if (clauses[winner].op == 0) { /* recv */
        while (wch->count == 0) pthread_cond_wait(&wch->not_empty, &wch->lock);
        clauses[winner].val = wch->buf[wch->head];
        wch->head = (wch->head + 1) % wch->cap; wch->count--;
        pthread_cond_signal(&wch->not_full);
        tur_waiter_signal_one(wch->send_waiters);
    } else { /* send */
        while (wch->count == wch->cap) pthread_cond_wait(&wch->not_full, &wch->lock);
        wch->buf[wch->tail] = clauses[winner].val;
        wch->tail = (wch->tail + 1) % wch->cap; wch->count++;
        pthread_cond_signal(&wch->not_empty);
        tur_waiter_signal_one(wch->recv_waiters);
    }
    pthread_mutex_unlock(&wch->lock);
    pthread_mutex_destroy(&wakeup_mutex);
    pthread_cond_destroy(&wakeup_cond);
    return winner;
}

/* rc<T> + weak<T> reference counting - Phase 9 */
/* Phase 10: GC color enum for Bacon-Rajan */
typedef enum { GC_WHITE, GC_GREY, GC_BLACK, GC_PURPLE } GcColor;

typedef void (*RcDropFn)(void *value);

typedef struct RcControlBlock RcControlBlock;

typedef void (*RcWalkChildFn)(RcControlBlock *child, void *ctx);
typedef void (*RcWalkFn)(void *value, RcWalkChildFn cb, void *ctx);

struct RcControlBlock {
    uint64_t strong_count;
    uint64_t weak_count;
    void *value;
    RcDropFn drop_fn;
    RcWalkFn walk_fn;
    uint8_t value_type_kind;
    uint8_t color;           /* GC color */
    bool may_contain_cycles;  /* Hint for GC */
    uint32_t gc_index;        /* CG0: slot in gc_all_blocks, or RC_GC_INDEX_NONE */
    bool gc_buffered;         /* CG1: in the candidate-root buffer */
    uint64_t gc_trial;        /* CG2: scratch trial refcount */
    bool gc_collecting;       /* CG2: in the white set being freed */
    uint8_t reserved[6];
};

/* ---------------------------------------------------------------------------
 * DEDUP-1: RcControlBlock layout guard.
 *
 * This struct exists TWICE: here, and hand-written into every compiled program
 * by the compiler (emit_module.c). The two copies must stay layout-compatible,
 * because linking one against the other -- the end goal of de-duplicating them
 * -- silently mis-reads every field past the first divergence otherwise.
 *
 * They HAD diverged: `value_type_kind` and `color` were enums here (4 bytes)
 * and `uint8_t` in the emitted copy, shifting every GC field after them. Both
 * are fixed-width now, and these assertions pin the widths and the field order
 * so any future drift is a COMPILE error in whichever copy changed, instead of
 * a runtime mis-read. Three bugs this session (CG1, CG3, CG4) came from these
 * copies drifting apart; each was invisible to half the test suite.
 *
 * Deliberately no assertion on the total sizeof or on absolute offsets: those
 * are padding-dependent and would break on a different ABI without indicating
 * a real divergence. Field widths and relative order are what must match.
 *
 * Written with the typedef trick rather than _Static_assert because the emitted
 * programs are compiled as C99, and both copies carry the identical text.
 * --------------------------------------------------------------------------- */
#define RC_LAYOUT_ASSERT(name, cond) typedef char rc_layout_##name[(cond) ? 1 : -1]

RC_LAYOUT_ASSERT(strong_w,  sizeof(((RcControlBlock *)0)->strong_count)      == 8);
RC_LAYOUT_ASSERT(weak_w,    sizeof(((RcControlBlock *)0)->weak_count)        == 8);
RC_LAYOUT_ASSERT(vtk_w,     sizeof(((RcControlBlock *)0)->value_type_kind)   == 1);
RC_LAYOUT_ASSERT(color_w,   sizeof(((RcControlBlock *)0)->color)             == 1);
RC_LAYOUT_ASSERT(mcc_w,     sizeof(((RcControlBlock *)0)->may_contain_cycles) == 1);
RC_LAYOUT_ASSERT(index_w,   sizeof(((RcControlBlock *)0)->gc_index)          == 4);
RC_LAYOUT_ASSERT(buffered_w,sizeof(((RcControlBlock *)0)->gc_buffered)       == 1);
RC_LAYOUT_ASSERT(trial_w,   sizeof(((RcControlBlock *)0)->gc_trial)          == 8);
RC_LAYOUT_ASSERT(collect_w, sizeof(((RcControlBlock *)0)->gc_collecting)     == 1);
RC_LAYOUT_ASSERT(ord_1, offsetof(RcControlBlock, strong_count)  < offsetof(RcControlBlock, weak_count));
RC_LAYOUT_ASSERT(ord_2, offsetof(RcControlBlock, weak_count)    < offsetof(RcControlBlock, value));
RC_LAYOUT_ASSERT(ord_3, offsetof(RcControlBlock, value)         < offsetof(RcControlBlock, drop_fn));
RC_LAYOUT_ASSERT(ord_4, offsetof(RcControlBlock, drop_fn)       < offsetof(RcControlBlock, walk_fn));
RC_LAYOUT_ASSERT(ord_5, offsetof(RcControlBlock, walk_fn)       < offsetof(RcControlBlock, value_type_kind));
RC_LAYOUT_ASSERT(ord_6, offsetof(RcControlBlock, value_type_kind) < offsetof(RcControlBlock, color));
RC_LAYOUT_ASSERT(ord_7, offsetof(RcControlBlock, color)         < offsetof(RcControlBlock, may_contain_cycles));
RC_LAYOUT_ASSERT(ord_8, offsetof(RcControlBlock, may_contain_cycles) < offsetof(RcControlBlock, gc_index));
RC_LAYOUT_ASSERT(ord_9, offsetof(RcControlBlock, gc_index)      < offsetof(RcControlBlock, gc_buffered));
RC_LAYOUT_ASSERT(ord_10, offsetof(RcControlBlock, gc_buffered)  < offsetof(RcControlBlock, gc_trial));
RC_LAYOUT_ASSERT(ord_11, offsetof(RcControlBlock, gc_trial)     < offsetof(RcControlBlock, gc_collecting));
RC_LAYOUT_ASSERT(ord_12, offsetof(RcControlBlock, gc_collecting) < offsetof(RcControlBlock, reserved));

