/* rc<T> value-ownership shims for collections (see tur_hamt_val_ops). */
void __tur_rc_val_retain(void *__v) __attribute__((unused));
void __tur_rc_val_retain(void *__v) {
    if (__v) rc_strong_increment((RcControlBlock *)__v);
}
void __tur_rc_val_release(void *__v) __attribute__((unused));
